// Combinar los datos de los 3 mercados
const items = $input.all();

const marketData = {
  ibex: items[0]?.json || {},
  sp500: items[1]?.json || {},
  nikkei: items[2]?.json || {}
};

const today = new Date().toLocaleDateString('es-ES', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

return [{
  json: {
    date: today,
    markets: marketData
  }
}];

