// Extraer el HTML del response de Gemini
const response = $input.first().json;

let htmlContent = '';

// El contenido puede venir en diferentes formatos
if (response.text) {
  htmlContent = response.text;
} else if (response.output) {
  htmlContent = response.output;
} else if (response.content) {
  htmlContent = response.content;
} else {
  htmlContent = JSON.stringify(response);
}

// Limpiar marcadores de código si existen
htmlContent = htmlContent.replace(/```html\n?/gi, '').replace(/```\n?/gi, '');

return [{
  json: {
    emailHtml: htmlContent,
    subject: `📊 Informe de Mercados - ${new Date().toLocaleDateString('es-ES')}`
  }
}];
